using System;
using UnityEngine;
// JsonUtility is the shipping serializer: verify the complete live DTO, not a substitute serializer.
public static class PassengerCarePersistenceTests {
 static void Check(bool ok,string message){if(!ok)throw new Exception("PASSENGER_CARE_SAVE: "+message);}
 public static void Run(){
  var empty=new PassengerJobsSnapshot{presenceCaptured=true,hasCurrent=false,hasDrunk=false,hasReward=false,hasChoice=false,hasServiceZones=false,offerPresent=new[]{false,true,false},offers=new[]{null,new JobOffer{pickup=1,drop=3,fare=5000},null},trip=new FareTrip().Snapshot()};var emptySaved=JsonUtility.FromJson<PassengerJobsSnapshot>(JsonUtility.ToJson(empty));PassengerJobs.NormalizePresence(emptySaved);Check(emptySaved.current==null&&emptySaved.drunk==null&&emptySaved.reward==null&&emptySaved.choice==null&&emptySaved.serviceZones==null,"explicit presence protects Idle from serializer null-class placeholders");Check(emptySaved.offers[0]==null&&emptySaved.offers[1]!=null&&emptySaved.offers[2]==null,"explicit offer presence preserves empty call slots");empty.hasCurrent=true;empty.current=new JobOffer{pickup=2,drop=4,fare=3000};var pickupTrip=new FareTrip();pickupTrip.Accept(3000,90,180);empty.trip=pickupTrip.Snapshot();emptySaved=JsonUtility.FromJson<PassengerJobsSnapshot>(JsonUtility.ToJson(empty));PassengerJobs.NormalizePresence(emptySaved);Check(emptySaved.trip.state==TripState.ToPickup&&emptySaved.current.pickup==2&&emptySaved.drunk==null&&emptySaved.reward==null,"first ToPickup roundtrip has actual passenger and no fake drunk or reward");
  var care=new VehicleCare();care.Finish("vomited-trip",true);care.Refuse("refused-offer");var settings=PrototypeSettings.ForThreeDays();var economy=new EconomyLedger(settings);
  var trip=new FareTrip();trip.Accept(5000,90);trip.Board();trip.Tick(89);trip.LockArrival();
  var drunk=DrunkRideState.Create("saved-both",true,DrunkRideCase.Both);drunk.Advance(86,.8f);drunk=JsonUtility.FromJson<DrunkRideState>(JsonUtility.ToJson(drunk));Check(drunk.Warned&&!drunk.Vomited&&drunk.VisibleDialogue(true).Length>0,"warning and critical dialogue persist before event");Check(drunk.Advance(3,.8f),"restored warning completes without replay");drunk.Arrive(true);drunk.Advance(16,1);
  var request=new PassengerRequest();request.Begin("saved-trip",RequestKind.Quiet);request.Accept();request.CompleteGoal(true,"actual quiet ride");request.Finish();
  var reward=PassengerReward.CalculateDetailed(100,85,5000,5000,5,true,80,3,100,89,false);
  var jobs=new PassengerJobsSnapshot{current=new JobOffer{pickup=1,drop=4,fare=5000,requiredScore=85,seconds=90},offers=new JobOffer[3],trip=trip.Snapshot(),offerId="saved-offer",drunk=drunk,reward=reward,startSatisfaction=80,startDeficit=8,cleanBonus=3,referenceSeconds=100,boardingDistance=1000,completed=3,balance=15000,cooldown=new[]{0f,17f},request=new PassengerRequestUISnapshot{request=request.Snapshot(),observedTrip="saved-trip",etaSelected=true,etaAge=50,etaPredicted=70,lawBefore=2},manners=new DrivingMannersSnapshot{score=100,reasons=new[]{"필요한 제동 제외"}}};
  string json=JsonUtility.ToJson(jobs);var saved=JsonUtility.FromJson<PassengerJobsSnapshot>(json);var restoredTrip=new FareTrip();restoredTrip.Restore(saved.trip);var restoredRequest=new PassengerRequest();restoredRequest.Restore(saved.request.request);
  Check(restoredTrip.ArrivalLocked&&restoredTrip.ArrivedOnTime&&restoredTrip.Remaining==1,"first arrival/deadline preserved");Check(saved.drunk.Waiting&&saved.drunk.WaitElapsed==16&&saved.drunk.Vomited,"vomit and sleepy wait persisted");Check(saved.drunk.CanDisembark(true,true)&&!saved.drunk.CanDisembark(false,true),"restored15 second wake still needs safe stop");Check(saved.reward.Total==reward.Total&&saved.reward.timeDelta==reward.timeDelta,"frozen settlement unchanged");Check(saved.startSatisfaction==80&&saved.startDeficit==8&&saved.cleanBonus==3&&saved.referenceSeconds==100,"no random baseline or ETA reroll");Check(restoredRequest.SatisfactionDelta==5&&restoredRequest.Finish()==0,"finished request cannot replay deduction");Check(saved.manners.score==100&&saved.manners.reasons.Length==1,"manner observation restored");Check(saved.current.pickup==1&&saved.current.drop==4&&saved.cooldown[1]==17,"offer and stop wait DTO");
  var savedCare=VehicleCare.Restore(JsonUtility.FromJson<VehicleCareSnapshot>(JsonUtility.ToJson(care.Snapshot())));Check(savedCare.Cleanliness==10&&savedCare.AcceptanceLocked&&savedCare.Refusals==1&&!savedCare.Finish("vomited-trip",false),"care+refusal+idempotency roundtrip");
  var roadside=new FareTrip();roadside.Accept(3000,90);roadside.Board();string roadsideJson=JsonUtility.ToJson(roadside.Snapshot());Check(!roadsideJson.Contains("Infinity")&&!roadsideJson.Contains("NaN"),"roadside unlimited pickup serializes valid finite value");
  var plan=new ScenarioChoiceSnapshot{courseId="PS08",plan="다음 연결도로 우회",alternate=true,offered=true,completed=false};var planSaved=JsonUtility.FromJson<ScenarioChoiceSnapshot>(JsonUtility.ToJson(plan));Check(planSaved.alternate&&planSaved.offered&&planSaved.plan==plan.plan&&!planSaved.completed,"selected PS08 plan roundtrip");
  Debug.Log("PASSENGER_CARE_PERSISTENCE_TESTS_OK serializer=JsonUtility checks=14");
 }
}
